INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(498325, 48828, 6008, '<td valign="top">The non-traditional angle is interesting and does add something to it. It seems a little darkly lit so I''m wondering if this was using a high ISO hence some of the noise on the skin tones. With black and white images there really needs to be a little more contrast or else have much more dramatic lighting.</td>', 'The non-traditional angle is interesting and does add something to it. It seems a little darkly lit so I''m wondering if this was using a high ISO hence some of the noise on the skin tones. With black and white images there really needs to be a little more contrast or else have much more dramatic lighting.', '2003-11-29 10:22:34.000000', NULL, 1),
