(498503, 48818, 6870, '<td valign="top">I like the color here in the blue range. Nice frozen moment of time.</td>', 'I like the color here in the blue range. Nice frozen moment of time.', '2003-11-29 12:48:50.000000', NULL, 1),
(498504, 48953, 6870, '<td valign="top">Certainly a think worth photographing! I like how you are staring away from the camera, as if your love is too large to be captured on film. It would have been nice for the sky to have cooperated with something interesting, but lovely work.</td>', 'Certainly a think worth photographing! I like how you are staring away from the camera, as if your love is too large to be captured on film. It would have been nice for the sky to have cooperated with something interesting, but lovely work.', '2003-11-29 12:50:19.000000', NULL, 1),
