(498853, 48883, 509, '<td valign="top">I like the muted colors of this shot.  Very serene as well.  One of my favorites.</td>', 'I like the muted colors of this shot.  Very serene as well.  One of my favorites.', '2003-11-30 00:54:34.000000', NULL, 1),
(498855, 48847, 11078, '<td valign="top">This is a beautifil scene and I love the colours I just think the glare of the setting sun is a bit too bright blame nature for that<br/>I find when I take the sun or lights it seems to glare more on a digital image <br/>Over all a nice image</td>', 'This is a beautifil scene and I love the colours I just think the glare of the setting sun is a bit too bright blame nature for thatI find when I take the sun or lights it seems to glare more on a digital image Over all a nice image', '2003-11-30 00:55:24.000000', NULL, 1),
